'use strict';

/**
* Reflect the upper triangular part of a single-precision floating-point matrix `A` into the lower triangular part of another matrix `B`.
*
* @module @stdlib/blas/ext/base/ndarray/striu2tril
*
* @example
* var Float32Matrix = require( '@stdlib/ndarray/matrix/float32' );
* var scalar2ndarray = require( '@stdlib/ndarray/from-scalar' );
* var striu2tril = require( '@stdlib/blas/ext/base/ndarray/striu2tril' );
*
* var A = new Float32Matrix( [ [ 1.0, 2.0 ], [ 3.0, 4.0 ] ] );
* var B = new Float32Matrix( [ [ 0.0, 0.0 ], [ 0.0, 0.0 ] ] );
*
* var k = scalar2ndarray( 0, {
*     'dtype': 'int32'
* });
*
* var out = striu2tril( [ A, B, k ] );
* // returns <ndarray>[ [ 1.0, 0.0 ], [ 2.0, 4.0 ] ]
*
* var bool = ( out === B );
* // returns true
*/

// MODULES //

var join = require( 'path' ).join;
var tryRequire = require( '@stdlib/utils/try-require' );
var isError = require( '@stdlib/assert/is-error' );
var main = require( './main.js' );


// MAIN //

var striu2tril;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	striu2tril = main;
} else {
	striu2tril = tmp;
}


// EXPORTS //

module.exports = striu2tril;
